//! OUTPUT form attributes drive native owner/reset selection and actual paint.
use super::*;
struct Fixture(std::path::PathBuf);
impl Drop for Fixture{fn drop(&mut self){let _=std::fs::remove_file(&self.0);}}
fn node(app:&App,id:&str)->usize{let mut pending=vec![0];while let Some(n)=pending.pop(){if app.document.dom_attr(n,"id").is_some_and(|v|v.raw_units().is_none()&&v.as_str()==id){return n;}pending.extend(app.document.nodes[n].children.iter().rev().copied());}panic!("connected node {id}")}
#[test]
fn output_form_attribute_actual_app_pointer_owner_reset_paint_and_interaction(){
 let file=Fixture(std::env::temp_dir().join(format!("chezcat-app-output-form-attribute-{}.html",std::process::id())));
 std::fs::write(&file.0,r#"<!doctype html><style>body{margin:0;background:white}output{display:block;position:absolute;left:20px;top:20px;width:120px;height:32px;background:#114455}output[form="owner"]{background:#cc2244}#go{position:absolute;left:220px;top:20px;width:160px;height:32px}#neighbor{position:absolute;left:220px;top:100px;width:180px;height:30px}#stable{position:absolute;left:420px;top:100px}label{position:absolute;left:20px;top:100px}</style><body><form id=owner><label id=label for=output>Result</label><output id=output for=seed form=owner name=result>ready</output><button id=resetowner type=reset style='position:absolute;left:220px;top:60px;width:120px;height:30px'>Reset owner</button></form><form id=other><button id=resetother type=reset style='position:absolute;left:400px;top:60px;width:120px;height:30px'>Reset other</button></form><button id=check type=button style='position:absolute;left:20px;top:200px;width:120px;height:30px'>Check reset</button><input id=neighbor value=neighbor><a id=stable href=#destination>Go</a><button id=go type=button>Change references</button><div id=destination></div><script>var output=document.getElementById('output'),attr=output.getAttributeNode('form'),labels=output.labels,tokens=output.htmlFor,round=0,stage=0;document.getElementById('check').onclick=function(e){if(!e.isTrusted)throw 'native pointer';if(stage===0){if(output.value!=='current'||output.defaultValue!=='ready')throw 'unassociated reset';}else{if(output.value!=='ready'||output.defaultValue!==output.value)throw 'actual associated reset';}stage++;};document.getElementById('go').onclick=function(e){if(!e.isTrusted)throw 'native pointer event';output.value='current';stage=0;var value=round===1?'owner':'other',watch=new MutationObserver(function(){}),old=attr.value;watch.observe(output,{attributes:true,attributeOldValue:true});if(round===0)output.setAttribute('form',value);else if(round===1)attr.value=value;else output.setAttributeNS(null,'form',value);var records=watch.takeRecords(),expected=document.getElementById(value);if(output.form!==expected||labels[0].form!==expected||labels[0].control!==output||output.labels!==labels||output.htmlFor!==tokens||tokens.value!=='seed'||output.name!=='result'||output.getAttributeNode('form')!==attr||attr.value!==value||records.length!==1||records[0].oldValue!==old)throw 'native form attribute';watch.disconnect();document.title='Output form '+round;round++;};</script>"#).unwrap();
 let mut app=App::new();app.resize(640,480);app.set_javascript_enabled(true);app.open(&file.0);assert!(!app.failed&&!app.is_loading(),"{}",app.status);assert_eq!(app.scripting.as_ref().unwrap().error_count(),0);let initial=app.draw();assert_eq!(initial.pixels[(app.content_top()+40)as usize*initial.width+110],0xcc2244);
 let go=node(&app,"go");let click=|app:&mut App,id:&str|{let n=node(app,id);let r=app.page.controls.iter().find(|r|r.node==n).unwrap();let(x,y)=(r.x+r.width/2,app.content_top()+r.y+r.height/2-app.scroll);app.pointer_down(x,y,false);app.pointer_up(x,y);assert_eq!(app.scripting.as_ref().unwrap().error_count(),0,"{}",app.scripting.as_ref().unwrap().report());assert!(!app.failed,"{}",app.status);};let neighbor=node(&app,"neighbor");let stable=node(&app,"stable");app.forms.script_set_value(neighbor,"edited neighbor").unwrap();{let e=&mut app.forms.controls.get_mut(&neighbor).unwrap().value;e.cursor=5;e.anchor=2;e.offset=1;}let raw=app.raw.clone();let location=app.location.clone();let epoch=app.script_epoch;
 for round in 0..3{let rect=app.page.controls.iter().find(|r|r.node==go).unwrap();let(x,y)=(rect.x+rect.width/2,app.content_top()+rect.y+rect.height/2-app.scroll);app.pointer_down(x,y,false);app.pointer_up(x,y);assert_eq!(app.scripting.as_ref().unwrap().error_count(),0,"{}",app.scripting.as_ref().unwrap().report());assert_eq!(app.document.title,format!("Output form {round}"));let painted=app.draw();assert_eq!(painted.pixels[(app.content_top()+40)as usize*painted.width+110],if round==1{0xcc2244}else{0x114455});click(&mut app,if round==1{"resetother"}else{"resetowner"});click(&mut app,"check");click(&mut app,if round==1{"resetowner"}else{"resetother"});click(&mut app,"check");let e=&app.forms.controls[&neighbor].value;assert_eq!((e.text(),e.cursor,e.anchor,e.offset),("edited neighbor".into(),5,2,1));assert_eq!(app.page.link_node_at(430,110),Some(stable));assert_eq!(app.raw,raw);assert_eq!(app.location,location);assert_eq!(app.script_epoch,epoch);}
}
